INSERT dm_academic_weekly (contactId,weekStart,activitiesCompleted,activitiesPlanned,score,simulations,missingCourses,createdAt)
SELECT id, CAST(DATEADD(day,-7*w.k,@n) AS date), CASE w.k WHEN 2 THEN 6 ELSE 8 END, 10, CASE w.k WHEN 2 THEN 61 ELSE 68 END, CASE w.k WHEN 2 THEN 1 ELSE 2 END, N'Matemática', @n
FROM dm_contacts CROSS JOIN (VALUES (1),(2)) w(k) WHERE sourceKey IN ('SINT-007','SINT-008','SINT-009');
INSERT amp_messages (contactId,channel,direction,body,status,senderType,senderId,recipientKind,createdAt)
SELECT id,'WHATSAPP','IN',N'Me interesa el servicio. ¿Cuánto cuesta? ¿Hay descuento?','RECEIVED','CONTACT',CAST(id AS nvarchar(20)),'STUDENT',DATEADD(hour,-5,@n) FROM dm_contacts WHERE sourceKey='SINT-001';
